#!/bin/bash
# experiments_8h.sh [--old-generated-code] -- experiments within 8 hours: imperative SML and the main competitor on the first family column of every row of Fig. 2
# and 3 (Tables 5, 9, 13, 16, 19, 22, 26), size by size across the seven benchmarks, with code exports generated by an Isabelle build of the library.
# Setup (setup/setup.sh 8h) and then the measurements (run/run.sh 8h); both can also be run on their own.
# --old-generated-code measures the code exports the paper's numbers were made with (exports/campaign) instead.
# Takes 8 hours: Isabelle download and build, then the runs until the 8 hours since the start are used up.  Results: evaluation/results/<date>_8h/.
set -uo pipefail
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
bash "$here/setup/setup.sh" 8h "$@" || { echo "setup failed, see evaluation/work/setup_8h.log" >&2; exit 1; }
exec bash "$here/run/run.sh" 8h "$@"
